package xyz.toesinthesand.ashfall.salvage.site;

import com.mojang.serialization.Codec;
import com.mojang.serialization.DataResult;
import com.mojang.serialization.codecs.RecordCodecBuilder;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;

/**
 * An authored structure our own code places (the Wreck hull, crash sites), loaded from
 * {@code data/<ns>/ashfall/site_template/<id>.json}.
 * <p>
 * The format is a character grid rather than a structure NBT file on purpose: it is text, so it diffs and
 * reviews like the Lost Cities parts next to it, it is generated by {@code tools/sites/build_sites.py} the
 * same way the landmarks are, and every block id is checked when the template is first placed.
 * <p>
 * {@code layers} run bottom-up; each layer is a list of rows from north to south, and each row's characters
 * run west to east. A space leaves the world's block alone (so the terrain around a crater survives); every
 * other character must be in {@code palette}. The bottom {@code sink} layers sit below the surface.
 *
 * @param palette    character -> block state string ({@code minecraft:chest[facing=north]})
 * @param layers     the grid; every row of every layer must have the same length, every layer the same row count
 * @param sink       how many layers are buried below the ground surface
 * @param foundation block poured under the bottom layer's solid cells down to the ground (empty: none), so a
 *                   site on a slope does not float
 * @param loot       character -> loot table for containers placed from that character
 * @param markers    character -> marker name; positions are recorded at placement (for example {@code boss},
 *                   where a lair spawns its boss)
 */
public record SiteTemplate(Map<String, String> palette, List<List<String>> layers, int sink, String foundation,
		Map<String, String> loot, Map<String, String> markers) {
	/** Leaves the world's block untouched. */
	public static final char KEEP = ' ';

	public static final Codec<SiteTemplate> CODEC = RecordCodecBuilder.<SiteTemplate>create(i -> i.group(
			Codec.unboundedMap(Codec.STRING, Codec.STRING).fieldOf("palette").forGetter(SiteTemplate::palette),
			Codec.STRING.listOf().listOf().fieldOf("layers").forGetter(SiteTemplate::layers),
			Codec.intRange(0, 64).optionalFieldOf("sink", 0).forGetter(SiteTemplate::sink),
			Codec.STRING.optionalFieldOf("foundation", "").forGetter(SiteTemplate::foundation),
			Codec.unboundedMap(Codec.STRING, Codec.STRING).optionalFieldOf("loot", Map.of()).forGetter(SiteTemplate::loot),
			Codec.unboundedMap(Codec.STRING, Codec.STRING).optionalFieldOf("markers", Map.of()).forGetter(SiteTemplate::markers)
	).apply(i, SiteTemplate::new)).validate(SiteTemplate::validate);

	/** One non-space cell of the grid, in template coordinates (x east, y up, z south). */
	public record Cell(int x, int y, int z, char symbol) {
	}

	public int height() {
		return layers.size();
	}

	public int depth() {
		return layers.isEmpty() ? 0 : layers.getFirst().size();
	}

	public int width() {
		return depth() == 0 ? 0 : layers.getFirst().getFirst().length();
	}

	public char at(int x, int y, int z) {
		return layers.get(y).get(z).charAt(x);
	}

	/** Every cell that changes the world, bottom layer first, so supports exist before what stands on them. */
	public List<Cell> cells() {
		List<Cell> cells = new ArrayList<>();
		for (int y = 0; y < height(); y++) {
			for (int z = 0; z < depth(); z++) {
				String row = layers.get(y).get(z);
				for (int x = 0; x < row.length(); x++) {
					char c = row.charAt(x);
					if (c != KEEP) {
						cells.add(new Cell(x, y, z, c));
					}
				}
			}
		}
		return cells;
	}

	/** Cells whose character is a marker, with the marker's name. */
	public List<Map.Entry<String, Cell>> markerCells() {
		List<Map.Entry<String, Cell>> out = new ArrayList<>();
		for (Cell cell : cells()) {
			String name = markers.get(String.valueOf(cell.symbol()));
			if (name != null) {
				out.add(Map.entry(name, cell));
			}
		}
		return out;
	}

	/** Shape and palette checks that need no registry: run when the file loads, so a bad file fails loudly. */
	static DataResult<SiteTemplate> validate(SiteTemplate t) {
		if (t.layers.isEmpty() || t.layers.getFirst().isEmpty() || t.layers.getFirst().getFirst().isEmpty()) {
			return DataResult.error(() -> "site template has no cells");
		}
		int depth = t.depth(), width = t.width();
		for (int y = 0; y < t.layers.size(); y++) {
			List<String> layer = t.layers.get(y);
			if (layer.size() != depth) {
				int fy = y;
				return DataResult.error(() -> "layer " + fy + " has " + layer.size() + " rows, expected " + depth);
			}
			for (int z = 0; z < depth; z++) {
				String row = layer.get(z);
				if (row.length() != width) {
					int fy = y, fz = z;
					return DataResult.error(() -> "layer " + fy + " row " + fz + " is " + row.length() + " wide, expected " + width);
				}
				for (int x = 0; x < width; x++) {
					char c = row.charAt(x);
					if (c != KEEP && !t.palette.containsKey(String.valueOf(c))) {
						return DataResult.error(() -> "character '" + c + "' is not in the palette");
					}
				}
			}
		}
		if (t.sink > t.layers.size()) {
			return DataResult.error(() -> "sink " + t.sink + " is deeper than the template");
		}
		for (String key : t.palette.keySet()) {
			if (key.length() != 1) {
				return DataResult.error(() -> "palette key '" + key + "' must be one character");
			}
		}
		return DataResult.success(t);
	}
}
